/* Star Goose: readable byte-exact reconstruction, v2.
 * Читайте docs/ARCHITECTURE_RU.md и src/include/entity.inc.
 * Изменяются имена/комментарии/границы include; порядок и байты EXE неизменны.
 * Общие хвосты и дополнительные входы не превращены в новые CALL/RET.
 */
/* BEGIN src/include/encoding.inc */
/* GNU as, Intel syntax. {load}, {disp16}, ACC16 сохраняют исходную форму кодирования.
 * Не заменять их обычными инструкциями без повторной byte-exact проверки. */
.intel_syntax noprefix
.code16
.arch i8086
.section .text
.global mz_header, image_start, entry, file_end
.macro ACC16 op:req, value:req
    \op ax, OFFSET FLAT:.Limm_\@
    .set .Limm_\@, \value
.endm

/* END src/include/encoding.inc */
/* BEGIN src/include/constants.inc */
/* Числа здесь — форматы оригинала, не параметры нового движка. */
.equ DATA_SEGMENT,          0x03a5
.equ DATA_BASE,             0x3a50
.equ DATA_AND_STACK_SIZE,   0x9670
.equ CS_sprite_stride,     0x0d93
.equ CS_transparent_color, 0x0d95
.equ CS_transparent_pair,  0x0d96
.equ CS_entity_handlers,   0x105a
.equ ENTITY_SIZE,          23
.equ ENTITY_CAPACITY,      48
.equ WORLD_Y_MASK,         0x03ff
.equ WORLD_Y_PERIOD,       1024
.equ MAP_COLUMNS,          12
.equ MAP_ROWS,             64
.equ MAP_TILE_WIDTH,       24
.equ MAP_TILE_HEIGHT,      16
.equ SCREEN_STRIDE,        40
.equ MAP_STRIDE,           32
.equ PACKED_SOURCE_STRIDE, 160
.equ VIEWPORT_WIDTH,       256
.equ VIEWPORT_HEIGHT,      160
.equ EF_RENDER,            0x01
.equ EF_UPDATE,            0x02
.equ EF_MAP_OBJECT,        0x08
.equ EF_LARGE_ANCHOR,      0x10
.equ EF_SIDE,              0x20
.equ EF_PROJECTILE,        0x40
.equ EF_SENTINEL,          0x80
.equ CONTROL_LEFT,         0x01
.equ CONTROL_RIGHT,        0x02
.equ CONTROL_UP,           0x04
.equ CONTROL_DOWN,         0x08
.equ CONTROL_RIGHT_DEVICE, 0x20
