.equ CONTROL_FIRE,         0x80
/* CONTROL bit4 не получает выдуманного действия: см. poll_controls. */
/* BP смещения относятся к кадру ПОСЛЕ PUSH BP / MOV BP,SP. */
.equ BLIT_HEIGHT,          4
.equ BLIT_WIDTH,           6
.equ BLIT_Y,               8
.equ BLIT_X,               10
.equ TERRAIN_Y,            4
.equ TERRAIN_X,            6
