/* Клавиатура, мышь, PIT и DOS vectors
 * Физический порядок EXE сохранён. Контракты получены анализом, не авторскими символами.
 * docs/FUNCTIONS_RU.md — индекс; docs/PORTING_TO_C_RU.md — ограничения переноса. */


/* ========================================================================== 
 * keyboard_install  |  CS:0442
 * Назначение: Задаёт исходные scan-code, очищает 128 состояний и устанавливает свой INT 09h.
 * Вход: DS = сегмент игры.
 * Эффект/ограничения: Сохраняет старый вектор; использует REP STOSW без локального CLD.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type keyboard_install, @function
keyboard_install:

    # Установщик IRQ и таблица клавиш относятся к платформенному слою будущего порта.
    mov WORD PTR ds:[D_last_key_pointer], 0x0                        # CS:0442
    mov WORD PTR ds:[D_key_left], 0x4b                               # CS:0448
    mov WORD PTR ds:[D_key_right], 0x4d                              # CS:044E
    mov WORD PTR ds:[D_key_up], 0x48                                 # CS:0454
    mov WORD PTR ds:[D_key_down], 0x50                               # CS:045A
    mov WORD PTR ds:[D_key_fire], 0x39                               # CS:0460
    mov WORD PTR ds:[D_key_action_n], 0x31                           # CS:0466
    mov WORD PTR ds:[D_key_action_m], 0x32                           # CS:046C
    mov WORD PTR ds:[D_key_quit], 0x10                               # CS:0472
    mov ax, ds                                                       # CS:0478
    mov es, ax                                                       # CS:047A
    mov ax, 0x0                                                      # CS:047C
    mov cx, 0x40                                                     # CS:047F
    mov di, 0x8e8a                                                   # CS:0482
    rep stos WORD PTR es:[di], ax                                    # CS:0485
    mov al, 0x9                                                      # CS:0487
    mov ah, 0x35                                                     # CS:0489
    int 0x21                                                         # CS:048B
    mov WORD PTR ds:[D_old_keyboard_offset], bx                      # CS:048D
    mov WORD PTR ds:[D_old_keyboard_segment], es                     # CS:0491
    push ds                                                          # CS:0495
    mov dx, OFFSET keyboard_irq1 - image_start                       # CS:0496
    mov ax, cs                                                       # CS:0499
    mov ds, ax                                                       # CS:049B
    mov al, 0x9                                                      # CS:049D
    mov ah, 0x25                                                     # CS:049F
    int 0x21                                                         # CS:04A1
    pop ds                                                           # CS:04A3
    ret                                                              # CS:04A4

/* ========================================================================== 
 * keyboard_restore  |  CS:04A5
 * Назначение: Возвращает сохранённый INT 09h через DOS.
 * Вход: Сохранённые offset/segment.
 * Эффект/ограничения: DS восстанавливается после временной подстановки сегмента обработчика.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type keyboard_restore, @function
keyboard_restore:
    mov dx, WORD PTR ds:[D_old_keyboard_offset]                      # CS:04A5
    mov ax, ds:[D_old_keyboard_segment]                              # CS:04A9
    push ds                                                          # CS:04AC
    mov ds, ax                                                       # CS:04AD
    mov al, 0x9                                                      # CS:04AF
    mov ah, 0x25                                                     # CS:04B1
    int 0x21                                                         # CS:04B3
    pop ds                                                           # CS:04B5
    ret                                                              # CS:04B6

/* ========================================================================== 
 * keyboard_irq1  |  CS:04B7
 * Назначение: Читает scan-code, подтверждает IRQ и записывает make/break как 1/0.
 * Вход: Аппаратный вход INT 09h.
 * Эффект/ограничения: IRET; AX/BX/DS сохранены. Расширенные префиксы не декодируются в отдельные клавиши.
 * Возвраты в физическом диапазоне: iret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type keyboard_irq1, @function
keyboard_irq1:

    # IRQ ABI: сохранять регистры и возвращаться через IRET, не через RET.
    sti                                                              # CS:04B7
    push ax                                                          # CS:04B8
    push bx                                                          # CS:04B9
    push ds                                                          # CS:04BA
    mov ax, 0x40                                                     # CS:04BB
    mov ds, ax                                                       # CS:04BE
    in al, 0x60                                                      # CS:04C0
    push ax                                                          # CS:04C2
    in al, 0x61                                                      # CS:04C3
    {load} mov ah, al                                                # CS:04C5
    or al, 0x80                                                      # CS:04C7
    out 0x61, al                                                     # CS:04C9
    xchg al, ah                                                      # CS:04CB
    out 0x61, al                                                     # CS:04CD
    pop bx                                                           # CS:04CF
L_keyboard_irq1_04d0:
    .set relocation_04d1, . + 1
    mov ax, OFFSET DATA_SEGMENT                                      # CS:04D0
    mov ds, ax                                                       # CS:04D3
    mov bh, 0x0                                                      # CS:04D5
    test bl, 0x80                                                    # CS:04D7
    jne L_keyboard_irq1_04e3                                         # CS:04DA
    mov BYTE PTR [bx+D_keyboard_state], 0x1                          # CS:04DC
    jmp L_keyboard_irq1_04eb                                         # CS:04E1
L_keyboard_irq1_04e3:
    and bl, 0x7f                                                     # CS:04E3
    mov BYTE PTR [bx+D_keyboard_state], 0x0                          # CS:04E6
L_keyboard_irq1_04eb:
    mov al, 0x20                                                     # CS:04EB
    out 0x20, al                                                     # CS:04ED
    pop ds                                                           # CS:04EF
    pop bx                                                           # CS:04F0
    pop ax                                                           # CS:04F1
    iret                                                             # CS:04F2

/* ========================================================================== 
 * wait_scancode  |  CS:04F3
 * Назначение: Ищет нажатую клавишу, кроме F1–F4 и обоих Shift; повторяет сканирование до находки.
 * Вход: Нет аргументов.
 * Эффект/ограничения: AX = scan-code. Сам по себе не ждёт отпускания предыдущей клавиши.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type wait_scancode, @function
wait_scancode:
    cld                                                              # CS:04F3
L_wait_scancode_04f4:
    mov si, 0x8e8a                                                   # CS:04F4
L_wait_scancode_04f7:
    lods al, BYTE PTR ds:[si]                                        # CS:04F7
    cmp al, 0x0                                                      # CS:04F8
    je L_wait_scancode_0520                                          # CS:04FA
    {load} mov ax, si                                                # CS:04FC
    ACC16 sub, 0x8e8b                                                # CS:04FE
    ACC16 cmp, 0x3b                                                  # CS:0501
    je L_wait_scancode_0520                                          # CS:0504
    ACC16 cmp, 0x3c                                                  # CS:0506
    je L_wait_scancode_0520                                          # CS:0509
    ACC16 cmp, 0x3d                                                  # CS:050B
    je L_wait_scancode_0520                                          # CS:050E
    ACC16 cmp, 0x3e                                                  # CS:0510
    je L_wait_scancode_0520                                          # CS:0513
    ACC16 cmp, 0x2a                                                  # CS:0515
    je L_wait_scancode_0520                                          # CS:0518
    ACC16 cmp, 0x36                                                  # CS:051A
    je L_wait_scancode_0520                                          # CS:051D
    ret                                                              # CS:051F
L_wait_scancode_0520:
    cmp si, 0x8f0a                                                   # CS:0520
    jne L_wait_scancode_04f7                                         # CS:0524
    jmp L_wait_scancode_04f4                                         # CS:0526
    ret                                                              # CS:0528 | Не достигнуто текущим статическим CFG; не удалять.

/* ========================================================================== 
 * wait_keys_released  |  CS:0529
 * Назначение: Повторяет проход по 128 байтам, пока все клавиши не отпущены.
 * Вход: DS = сегмент игры; ожидается DF = 0.
 * Эффект/ограничения: Блокирующий busy loop.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type wait_keys_released, @function
wait_keys_released:
    mov si, 0x8e8a                                                   # CS:0529
    mov ah, 0x0                                                      # CS:052C
L_wait_keys_released_052e:
    lods al, BYTE PTR ds:[si]                                        # CS:052E
    cmp al, 0x0                                                      # CS:052F
    je L_wait_keys_released_0535                                     # CS:0531
    inc ah                                                           # CS:0533
L_wait_keys_released_0535:
    cmp si, 0x8f0a                                                   # CS:0535
    jne L_wait_keys_released_052e                                    # CS:0539
    cmp ah, 0x0                                                      # CS:053B
    jne wait_keys_released                                           # CS:053E
    ret                                                              # CS:0540

/* ========================================================================== 
 * poll_key_character  |  CS:0541
 * Назначение: До 20000 проходов ищет новый scan-code и переводит его через таблицу символов.
 * Вход: last_key_pointer подавляет повтор того же нажатия.
 * Эффект/ограничения: AL = символ либо 0. Это ограниченное ожидание, а не мгновенный poll.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type poll_key_character, @function
poll_key_character:
    mov cx, 0x4e20                                                   # CS:0541
L_poll_key_character_0544:
    mov si, 0x8e8a                                                   # CS:0544
    mov ah, 0x0                                                      # CS:0547
    cld                                                              # CS:0549
L_poll_key_character_054a:
    lods al, BYTE PTR ds:[si]                                        # CS:054A
    cmp al, 0x0                                                      # CS:054B
    je L_poll_key_character_0557                                     # CS:054D
    mov ah, 0x1                                                      # CS:054F
    cmp si, WORD PTR ds:[D_last_key_pointer]                         # CS:0551
    jne L_poll_key_character_055f                                    # CS:0555
L_poll_key_character_0557:
    cmp si, 0x8f0a                                                   # CS:0557
    je L_poll_key_character_055f                                     # CS:055B
    jmp L_poll_key_character_054a                                    # CS:055D
L_poll_key_character_055f:
    je L_poll_key_character_0578                                     # CS:055F
    mov WORD PTR ds:[D_last_key_pointer], si                         # CS:0561
    sub si, 0x8e8b                                                   # CS:0565
    {disp16} mov al, BYTE PTR [si+D_key_to_character]                # CS:0569 | Original disp16=005Ah deliberately retained, although disp8 would fit
    cmp al, 0x0                                                      # CS:056D
    je L_poll_key_character_0576                                     # CS:056F
    jns L_poll_key_character_0575                                    # CS:0571
    mov al, 0x0                                                      # CS:0573
L_poll_key_character_0575:
    ret                                                              # CS:0575
L_poll_key_character_0576:
    jmp L_poll_key_character_0583                                    # CS:0576
L_poll_key_character_0578:
    cmp ah, 0x0                                                      # CS:0578
    jne L_poll_key_character_0583                                    # CS:057B
    mov WORD PTR ds:[D_last_key_pointer], 0x0                        # CS:057D
L_poll_key_character_0583:
    loop L_poll_key_character_0544                                   # CS:0583
    mov al, 0x0                                                      # CS:0585
    ret                                                              # CS:0587

/* ========================================================================== 
 * mouse_reset  |  CS:0588
 * Назначение: Сбрасывает драйвер мыши INT 33h и сохраняет признак его наличия.
 * Вход: Нет аргументов.
 * Эффект/ограничения: mouse_present = AL результата AX=0/INT 33h.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type mouse_reset, @function
mouse_reset:
    mov ax, 0x0                                                      # CS:0588
    int 0x33                                                         # CS:058B
    mov ds:[D_mouse_present], al                                     # CS:058D
    ret                                                              # CS:0590

/* ========================================================================== 
 * timer_install  |  CS:0591
 * Назначение: Сохраняет и заменяет INT 1Ch; программирует PIT0 делителем 4D0Eh.
 * Вход: DS = сегмент игры.
 * Эффект/ограничения: Звук обновляется из обработчика, а не из главного игрового цикла.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type timer_install, @function
timer_install:

    # PIT обслуживает звук независимо от вертикальной синхронизации игрового кадра.
    mov al, 0x1c                                                     # CS:0591
    mov ah, 0x35                                                     # CS:0593
    int 0x21                                                         # CS:0595
    mov WORD PTR ds:[D_old_timer_offset], bx                         # CS:0597
    mov WORD PTR ds:[D_old_timer_segment], es                        # CS:059B
    push ds                                                          # CS:059F
    mov dx, OFFSET timer_int1c - image_start                         # CS:05A0
    mov ax, cs                                                       # CS:05A3
    mov ds, ax                                                       # CS:05A5
    mov al, 0x1c                                                     # CS:05A7
    mov ah, 0x25                                                     # CS:05A9
    int 0x21                                                         # CS:05AB | DOS installs INT 1Ch
    pop ds                                                           # CS:05AD
    mov al, 0x36                                                     # CS:05AE
    out 0x43, al                                                     # CS:05B0
    mov ax, 0x4d0e                                                   # CS:05B2
    out 0x40, al                                                     # CS:05B5
    {load} mov al, ah                                                # CS:05B7
    out 0x40, al                                                     # CS:05B9
    ret                                                              # CS:05BB

/* ========================================================================== 
 * timer_restore_vector  |  CS:05BC
 * Назначение: Возвращает только вектор INT 1Ch.
 * Вход: Сохранённые offset/segment.
 * Эффект/ограничения: Делитель PIT в этой процедуре не восстанавливается.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type timer_restore_vector, @function
timer_restore_vector:
    mov dx, WORD PTR ds:[D_old_timer_offset]                         # CS:05BC
    mov ax, ds:[D_old_timer_segment]                                 # CS:05C0
    push ds                                                          # CS:05C3
    mov ds, ax                                                       # CS:05C4
    mov al, 0x1c                                                     # CS:05C6
    mov ah, 0x25                                                     # CS:05C8
    int 0x21                                                         # CS:05CA
    pop ds                                                           # CS:05CC
    ret                                                              # CS:05CD

/* ========================================================================== 
 * timer_int1c  |  CS:05CE
 * Назначение: Увеличивает 8-битный счётчик тиков и обновляет звуковой автомат.
 * Вход: Вход прерывания; свой DS устанавливается явно.
 * Эффект/ограничения: IRET; tick переполняется по модулю 256. Общие регистры и DS сохранены, ES явно не сохраняется.
 * Возвраты в физическом диапазоне: iret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type timer_int1c, @function
timer_int1c:
    sti                                                              # CS:05CE
    push ax                                                          # CS:05CF
    push bx                                                          # CS:05D0
    push cx                                                          # CS:05D1
    push dx                                                          # CS:05D2
    push si                                                          # CS:05D3
    push di                                                          # CS:05D4
    push bp                                                          # CS:05D5
    push ds                                                          # CS:05D6
L_timer_int1c_05d7:
    .set relocation_05d8, . + 1
    mov ax, OFFSET DATA_SEGMENT                                      # CS:05D7
    mov ds, ax                                                       # CS:05DA
    inc BYTE PTR ds:[D_timer_ticks]                                  # CS:05DC
    call sound_tick                                                  # CS:05E0
    pop ds                                                           # CS:05E3
    pop bp                                                           # CS:05E4
    pop di                                                           # CS:05E5
    pop si                                                           # CS:05E6
    pop dx                                                           # CS:05E7
    pop cx                                                           # CS:05E8
    pop bx                                                           # CS:05E9
    pop ax                                                           # CS:05EA
    iret                                                             # CS:05EB

/* ========================================================================== 
 * critical_error_install  |  CS:05EC
 * Назначение: Устанавливает минимальный INT 24h.
 * Вход: DS = сегмент игры.
 * Эффект/ограничения: Старый вектор здесь не сохраняется.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type critical_error_install, @function
critical_error_install:
    push ds                                                          # CS:05EC
    mov dx, OFFSET critical_error_int24 - image_start                # CS:05ED
    mov ax, cs                                                       # CS:05F0
    mov ds, ax                                                       # CS:05F2
    mov al, 0x24                                                     # CS:05F4
    mov ah, 0x25                                                     # CS:05F6
    int 0x21                                                         # CS:05F8
    pop ds                                                           # CS:05FA
    ret                                                              # CS:05FB

/* ========================================================================== 
 * critical_error_int24  |  CS:05FC
 * Назначение: Возвращает AL=0 обработчику критической ошибки DOS.
 * Вход: Вход прерывания.
 * Эффект/ограничения: IRET; не обычный RET и не логическая функция игры.
 * Возвраты в физическом диапазоне: iret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type critical_error_int24, @function
critical_error_int24:
    sti                                                              # CS:05FC
    mov al, 0x0                                                      # CS:05FD
    iret                                                             # CS:05FF

/* END src/code/03_dos_interrupts.asm */
/* BEGIN src/code/04_resource_io.asm */
/* Загрузка ресурсов и файловый I/O
 * Физический порядок EXE сохранён. Контракты получены анализом, не авторскими символами.
 * docs/FUNCTIONS_RU.md — индекс; docs/PORTING_TO_C_RU.md — ограничения переноса. */


/* ========================================================================== 
 * load_assets  |  CS:0600
 * Назначение: Загружает BIRD1, BIRD2, BLOX, NEWBIRD, PODZ1 и INTRO в отдельные буферы.
 * Вход: Сегменты буферов уже назначены entry.
 * Эффект/ограничения: Шесть чтений по 32000 байт. Формат использования не одинаков у всех .X.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type load_assets, @function
load_assets:

    # Шесть чтений по 32000 байт. Это исходные форматы ресурсов, не шесть одинаковых PNG.
    mov dx, OFFSET D_filename_bird1                                  # CS:0600
    mov ax, ds:[D_segment_bird1]                                     # CS:0603
    call load_32000_bytes                                            # CS:0606
    mov dx, OFFSET D_filename_bird2                                  # CS:0609
    mov ax, ds:[D_segment_bird2]                                     # CS:060C
    call load_32000_bytes                                            # CS:060F
    mov dx, OFFSET D_filename_blox                                   # CS:0612
    mov ax, ds:[D_segment_blox]                                      # CS:0615
    call load_32000_bytes                                            # CS:0618
    mov dx, OFFSET D_filename_newbird                                # CS:061B
    mov ax, ds:[D_segment_newbird]                                   # CS:061E
    call load_32000_bytes                                            # CS:0621
    mov dx, OFFSET D_filename_podz1                                  # CS:0624
    mov ax, ds:[D_segment_podz1]                                     # CS:0627
    call load_32000_bytes                                            # CS:062A
    mov dx, OFFSET D_filename_intro                                  # CS:062D
    mov ax, ds:[D_segment_intro]                                     # CS:0630
    call load_32000_bytes                                            # CS:0633
    ret                                                              # CS:0636

/* ========================================================================== 
 * load_32000_bytes  |  CS:0637
 * Назначение: Обёртка чтения полного ресурса в segment:0000.
 * Вход: AX = сегмент назначения; DS:DX = имя.
 * Эффект/ограничения: DI=0, CX=32000; затем файловый reader.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type load_32000_bytes, @function
load_32000_bytes:
    mov ds:[D_file_destination_segment], ax                          # CS:0637
    mov di, 0x0                                                      # CS:063A
    mov cx, 0x7d00                                                   # CS:063D
    call dos_open_read_close                                         # CS:0640
    ret                                                              # CS:0643

/* ========================================================================== 
 * load_file_to_ds  |  CS:0644
 * Назначение: Выбирает текущий DS как сегмент назначения и читает файл.
 * Вход: DS:DX = имя; DI = адрес назначения; CX = длина.
 * Эффект/ограничения: Используется для HISCORES.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type load_file_to_ds, @function
load_file_to_ds:
    mov ax, ds                                                       # CS:0644
    mov ds:[D_file_destination_segment], ax                          # CS:0646
    call dos_open_read_close                                         # CS:0649
    ret                                                              # CS:064C

/* ========================================================================== 
 * dos_open_read_close  |  CS:064D
 * Назначение: Открывает файл, читает блок и закрывает handle.
 * Вход: DS:DX = имя; DI = offset; CX = count; file_destination_segment = сегмент.
 * Эффект/ограничения: Ошибка open возвращается; результат read не проверяется до close. Не считать AX надёжным числом прочитанных байтов.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type dos_open_read_close, @function
dos_open_read_close:
    push di                                                          # CS:064D
    push cx                                                          # CS:064E
    mov ax, 0x3d00                                                   # CS:064F
    int 0x21                                                         # CS:0652
    pop cx                                                           # CS:0654
    pop dx                                                           # CS:0655
    jae L_dos_open_read_close_0659                                   # CS:0656
    ret                                                              # CS:0658
L_dos_open_read_close_0659:
    mov ds:[D_file_handle], ax                                       # CS:0659
    {load} mov bx, ax                                                # CS:065C
    mov ax, ds:[D_file_destination_segment]                          # CS:065E
    push ds                                                          # CS:0661
    mov ds, ax                                                       # CS:0662
    mov ax, 0x3f00                                                   # CS:0664
    int 0x21                                                         # CS:0667
    pop ds                                                           # CS:0669
    mov ax, 0x3e00                                                   # CS:066A
    mov bx, WORD PTR ds:[D_file_handle]                              # CS:066D
    int 0x21                                                         # CS:0671
    ret                                                              # CS:0673

/* ========================================================================== 
 * dos_create_write_close  |  CS:0674
 * Назначение: Создаёт/обнуляет файл и записывает блок.
 * Вход: DS:DX = имя; DS:DI = данные; CX = длина.
 * Эффект/ограничения: При ошибке write выходит без close; сохранено, а не исправлено.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type dos_create_write_close, @function
dos_create_write_close:
    push di                                                          # CS:0674
    push cx                                                          # CS:0675
    mov cx, 0x0                                                      # CS:0676
    mov ax, 0x3c00                                                   # CS:0679
    int 0x21                                                         # CS:067C
    pop cx                                                           # CS:067E
    pop dx                                                           # CS:067F
    jae L_dos_create_write_close_0683                                # CS:0680
    ret                                                              # CS:0682
L_dos_create_write_close_0683:
    mov ds:[D_file_handle], ax                                       # CS:0683
    {load} mov bx, ax                                                # CS:0686
    mov ax, 0x4000                                                   # CS:0688
    int 0x21                                                         # CS:068B
    jae L_dos_create_write_close_0690                                # CS:068D
    ret                                                              # CS:068F
L_dos_create_write_close_0690:
    mov ax, 0x3e00                                                   # CS:0690
    mov bx, WORD PTR ds:[D_file_handle]                              # CS:0693
    int 0x21                                                         # CS:0697
    ret                                                              # CS:0699

/* END src/code/04_resource_io.asm */
/* BEGIN src/code/05_world_map.asm */
/* RLE карты, рельеф, размещение и столкновения
 * Физический порядок EXE сохранён. Контракты получены анализом, не авторскими символами.
 * docs/FUNCTIONS_RU.md — индекс; docs/PORTING_TO_C_RU.md — ограничения переноса. */


/* ========================================================================== 
 * prepare_level_maps  |  CS:069A
 * Назначение: Декодирует поток тайлов 12×64 и 64 маски размещения; рисует карту в кольцевой фон A800h.
 * Вход: level_index, level_part; RLE-таблицы в DS.
 * Эффект/ограничения: RLE: нижние 6 бит = tile, верхние 2 = длина минус 1. Ровно 768 выходных байтов.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type prepare_level_maps, @function
prepare_level_maps:

    # level_index*3 + level_part выбирает и карту тайлов, и размещение объектов.
    mov al, ds:[D_level_index]                                       # CS:069A
    {load} mov bl, al                                                # CS:069D
    shl bl, 1                                                        # CS:069F
    {load} add bl, al                                                # CS:06A1
    add bl, BYTE PTR ds:[D_level_part]                               # CS:06A3
    mov bh, 0x0                                                      # CS:06A7
    shl bx, 1                                                        # CS:06A9
    mov si, WORD PTR [bx+D_level_object_streams]                     # CS:06AB
    mov di, 0x9229                                                   # CS:06AF
    mov cx, 0x40                                                     # CS:06B2
    mov ax, ds                                                       # CS:06B5
    mov es, ax                                                       # CS:06B7
    mov ax, 0x0                                                      # CS:06B9
    cld                                                              # CS:06BC
    rep stos WORD PTR es:[di], ax                                    # CS:06BD
    mov di, 0x9229                                                   # CS:06BF
L_map_next_placement:

    # Тройка kind/column/source_row. В stored row OR-ятся kind<<10 и бит колонки.
    lods al, BYTE PTR ds:[si]                                        # CS:06C2
    cmp al, 0xff                                                     # CS:06C3
    je L_map_decode_tile_stream                                      # CS:06C5
    shl al, 1                                                        # CS:06C7
    shl al, 1                                                        # CS:06C9
    {load} mov ah, al                                                # CS:06CB
    lods al, BYTE PTR ds:[si]                                        # CS:06CD
    shl al, 1                                                        # CS:06CE
    {load} mov bl, al                                                # CS:06D0
    mov bh, 0x0                                                      # CS:06D2
    mov al, 0x0                                                      # CS:06D4
    or ax, WORD PTR [bx+D_map_column_bits]                           # CS:06D6
    {load} mov cx, ax                                                # CS:06DA
    lods al, BYTE PTR ds:[si]                                        # CS:06DC
    neg al                                                           # CS:06DD
    add al, 0x3f                                                     # CS:06DF
    shl al, 1                                                        # CS:06E1
    {load} mov bl, al                                                # CS:06E3
    or WORD PTR [bx+D_map_spawn_rows], cx                            # CS:06E5
    jmp L_map_next_placement                                         # CS:06E9
L_map_decode_tile_stream:

    # RLE: младшие 6 бит — tile; старшие 2 — число повторений минус один.
    mov al, ds:[D_level_index]                                       # CS:06EB
    {load} mov bl, al                                                # CS:06EE
    shl bl, 1                                                        # CS:06F0
    {load} add bl, al                                                # CS:06F2
    add bl, BYTE PTR ds:[D_level_part]                               # CS:06F4
    mov bh, 0x0                                                      # CS:06F8
    shl bx, 1                                                        # CS:06FA
    mov si, WORD PTR [bx+D_level_tile_streams]                       # CS:06FC
    mov di, 0x8f29                                                   # CS:0700
    mov cx, 0x300                                                    # CS:0703
    mov bl, 0x0                                                      # CS:0706
L_map_next_decoded_tile:

    # BL — оставшиеся повторы. Декодируем ровно 12*64 клеток, без отдельного EOF.
    dec bl                                                           # CS:0708
    jns L_map_write_decoded_tile                                     # CS:070A
    lods al, BYTE PTR ds:[si]                                        # CS:070C
    {load} mov dl, al                                                # CS:070D
    and dl, 0x3f                                                     # CS:070F
    and al, 0xc0                                                     # CS:0712
    jne L_prepare_level_maps_071a                                    # CS:0714
    mov bl, 0x0                                                      # CS:0716
    jmp L_map_write_decoded_tile                                     # CS:0718
L_prepare_level_maps_071a:
    cmp al, 0x40                                                     # CS:071A
    jne L_prepare_level_maps_0722                                    # CS:071C
    mov bl, 0x1                                                      # CS:071E
    jmp L_map_write_decoded_tile                                     # CS:0720
L_prepare_level_maps_0722:
    cmp al, 0x80                                                     # CS:0722
    jne L_prepare_level_maps_072a                                    # CS:0724
    mov bl, 0x2                                                      # CS:0726
    jmp L_map_write_decoded_tile                                     # CS:0728
L_prepare_level_maps_072a:
    mov bl, 0x3                                                      # CS:072A
L_map_write_decoded_tile:
    mov BYTE PTR [di], dl                                            # CS:072C
    inc di                                                           # CS:072E
    loop L_map_next_decoded_tile                                     # CS:072F

    # Рисуем кольцевую карту в A800. Это video-memory cache, а не логическая карта столкновений.
    mov di, 0x0                                                      # CS:0731
    mov ax, 0xa800                                                   # CS:0734
    mov es, ax                                                       # CS:0737
    mov dx, 0x3ce                                                    # CS:0739
    mov ah, 0x0                                                      # CS:073C
    mov al, 0x0                                                      # CS:073E
    out dx, ax                                                       # CS:0740
    mov ax, 0xf01                                                    # CS:0741
    out dx, ax                                                       # CS:0744
    mov cx, 0x4000                                                   # CS:0745
    rep stos WORD PTR es:[di], ax                                    # CS:0748
    mov ax, 0x8f29                                                   # CS:074A
    mov ds:[D_map_tile_cursor], ax                                   # CS:074D
    mov WORD PTR ds:[D_map_row_y], 0x3f0                             # CS:0750
    mov cx, 0x40                                                     # CS:0756
L_map_prerender_row:

    # Каждая строка: 8 px левого края + 10*24 px середины + 8 px правого края = 256 px.
    push cx                                                          # CS:0759
    mov BYTE PTR ds:[D_map_running_height], 0x0                      # CS:075A
