    mov BYTE PTR [si+0xb], al                                        # CS:0A3B
    mov al, BYTE PTR [di+0xc]                                        # CS:0A3E
    mov BYTE PTR [si+0xc], al                                        # CS:0A41
    mov ax, WORD PTR [di+0xf]                                        # CS:0A44
    mov WORD PTR [si+0xf], ax                                        # CS:0A47
    mov al, BYTE PTR [di+0x12]                                       # CS:0A4A
    mov BYTE PTR [si+0x12], al                                       # CS:0A4D
    ret                                                              # CS:0A50

/* ========================================================================== 
 * query_player_map_collision  |  CS:0A51
 * Назначение: Ищет препятствие текущей строки около x игрока по маскам и ширинам из таблиц.
 * Вход: player_map_row, player_x, level_part.
 * Эффект/ограничения: AX=код/величина столкновения либо 0; BX=колонка при попадании.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type query_player_map_collision, @function
query_player_map_collision:
    mov bl, BYTE PTR ds:[D_player_map_row]                           # CS:0A51
    mov bh, 0x0                                                      # CS:0A55
    shl bx, 1                                                        # CS:0A57
    {load} mov si, bx                                                # CS:0A59
    mov al, ds:[D_level_part]                                        # CS:0A5B
    cmp al, 0x1                                                      # CS:0A5E
    jne L_query_player_map_collision_0a68                            # CS:0A60
    add si, 0x80                                                     # CS:0A62
    jmp L_query_player_map_collision_0a70                            # CS:0A66
L_query_player_map_collision_0a68:
    cmp al, 0x2                                                      # CS:0A68
    jne L_query_player_map_collision_0a70                            # CS:0A6A
    add si, 0x100                                                    # CS:0A6C
L_query_player_map_collision_0a70:
    mov ax, WORD PTR [si+D_map_available_masks]                      # CS:0A70
    and ax, WORD PTR [bx+D_map_spawn_rows]                           # CS:0A74
    ACC16 cmp, 0x0                                                   # CS:0A78
    je L_query_player_map_collision_0ad1                             # CS:0A7B
    {load} mov bl, ah                                                # CS:0A7D
    shr bl, 1                                                        # CS:0A7F
    shr bl, 1                                                        # CS:0A81
    mov bh, 0x0                                                      # CS:0A83
    mov cl, BYTE PTR [bx+D_map_collision_damage]                     # CS:0A85
    cmp cl, 0x0                                                      # CS:0A89
    je L_query_player_map_collision_0ad1                             # CS:0A8C
    mov BYTE PTR ds:[D_collision_damage_tmp], cl                     # CS:0A8E
    mov WORD PTR ds:[D_collision_column_tmp], 0xa                    # CS:0A92
    shl bx, 1                                                        # CS:0A98
    mov dx, WORD PTR [bx+D_map_collision_halfwidth]                  # CS:0A9A
    mov bx, WORD PTR [bx+D_map_collision_rightmost_x]                # CS:0A9E
    mov cx, 0xa                                                      # CS:0AA2
L_query_player_map_collision_0aa5:
    shr ax, 1                                                        # CS:0AA5
    jae L_query_player_map_collision_0ac8                            # CS:0AA7
    push bx                                                          # CS:0AA9
    {load} sub bx, dx                                                # CS:0AAA
    cmp bx, WORD PTR ds:[D_player_x]                                 # CS:0AAC
    jg L_query_player_map_collision_0ac7                             # CS:0AB0
    {load} add bx, dx                                                # CS:0AB2
    {load} add bx, dx                                                # CS:0AB4
    cmp bx, WORD PTR ds:[D_player_x]                                 # CS:0AB6
    jl L_query_player_map_collision_0ac7                             # CS:0ABA
    pop ax                                                           # CS:0ABC
    mov al, ds:[D_collision_damage_tmp]                              # CS:0ABD
    mov ah, 0x0                                                      # CS:0AC0
    mov bx, WORD PTR ds:[D_collision_column_tmp]                     # CS:0AC2
    ret                                                              # CS:0AC6
L_query_player_map_collision_0ac7:
    pop bx                                                           # CS:0AC7
L_query_player_map_collision_0ac8:
    sub bx, 0x18                                                     # CS:0AC8
    dec WORD PTR ds:[D_collision_column_tmp]                         # CS:0ACB
    loop L_query_player_map_collision_0aa5                           # CS:0ACF
L_query_player_map_collision_0ad1:
    mov ax, 0x0                                                      # CS:0AD1
    ret                                                              # CS:0AD4

/* ========================================================================== 
 * query_map_collision_at  |  CS:0AD5
 * Назначение: Проверяет препятствие строки для переданного x, с уменьшением полуширины на 14.
 * Вход: [BP+4]=row; [BP+6]=x.
 * Эффект/ограничения: AX=0/1, BX=колонка при попадании; RET 4.
 * Возвраты в физическом диапазоне: ret 0x4.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type query_map_collision_at, @function
query_map_collision_at:
    push bp                                                          # CS:0AD5
    {load} mov bp, sp                                                # CS:0AD6
    mov bx, WORD PTR [bp+0x4]                                        # CS:0AD8
    shl bx, 1                                                        # CS:0ADB
    {load} mov si, bx                                                # CS:0ADD
    mov al, ds:[D_level_part]                                        # CS:0ADF
    cmp al, 0x1                                                      # CS:0AE2
    jne L_query_map_collision_at_0aec                                # CS:0AE4
    add si, 0x80                                                     # CS:0AE6
    jmp L_query_map_collision_at_0af4                                # CS:0AEA
L_query_map_collision_at_0aec:
    cmp al, 0x2                                                      # CS:0AEC
    jne L_query_map_collision_at_0af4                                # CS:0AEE
    add si, 0x100                                                    # CS:0AF0
L_query_map_collision_at_0af4:
    mov ax, WORD PTR [si+D_map_available_masks]                      # CS:0AF4
    and ax, WORD PTR [bx+D_map_spawn_rows]                           # CS:0AF8
    ACC16 cmp, 0x0                                                   # CS:0AFC
    je L_query_map_collision_at_0b51                                 # CS:0AFF
    {load} mov bl, ah                                                # CS:0B01
    shr bl, 1                                                        # CS:0B03
    shr bl, 1                                                        # CS:0B05
    mov bh, 0x0                                                      # CS:0B07
    mov cl, BYTE PTR [bx+D_map_collision_damage]                     # CS:0B09
    cmp cl, 0x0                                                      # CS:0B0D
    je L_query_map_collision_at_0b51                                 # CS:0B10
    mov WORD PTR ds:[D_collision_column_tmp], 0xa                    # CS:0B12
    shl bx, 1                                                        # CS:0B18
    mov dx, WORD PTR [bx+D_map_collision_halfwidth]                  # CS:0B1A
    sub dx, 0xe                                                      # CS:0B1E
    mov bx, WORD PTR [bx+D_map_collision_rightmost_x]                # CS:0B21
    mov cx, 0xa                                                      # CS:0B25
L_query_map_collision_at_0b28:
    shr ax, 1                                                        # CS:0B28
    jae L_query_map_collision_at_0b48                                # CS:0B2A
    push bx                                                          # CS:0B2C
    {load} sub bx, dx                                                # CS:0B2D
    cmp bx, WORD PTR [bp+0x6]                                        # CS:0B2F
    jg L_query_map_collision_at_0b47                                 # CS:0B32
    {load} add bx, dx                                                # CS:0B34
    {load} add bx, dx                                                # CS:0B36
    cmp bx, WORD PTR [bp+0x6]                                        # CS:0B38
    jl L_query_map_collision_at_0b47                                 # CS:0B3B
    pop ax                                                           # CS:0B3D
    mov ax, 0x1                                                      # CS:0B3E
    mov bx, WORD PTR ds:[D_collision_column_tmp]                     # CS:0B41
    jmp L_query_map_collision_at_0b54                                # CS:0B45
L_query_map_collision_at_0b47:
    pop bx                                                           # CS:0B47
L_query_map_collision_at_0b48:
    sub bx, 0x18                                                     # CS:0B48
    dec WORD PTR ds:[D_collision_column_tmp]                         # CS:0B4B
    loop L_query_map_collision_at_0b28                               # CS:0B4F
L_query_map_collision_at_0b51:
    mov ax, 0x0                                                      # CS:0B51
L_query_map_collision_at_0b54:
    pop bp                                                           # CS:0B54
    ret 0x4                                                          # CS:0B55

/* END src/code/05_world_map.asm */
/* BEGIN src/code/06_entity_pool.asm */
/* Пул, обход рендера и подготовка спрайтов
 * Физический порядок EXE сохранён. Контракты получены анализом, не авторскими символами.
 * docs/FUNCTIONS_RU.md — индекс; docs/PORTING_TO_C_RU.md — ограничения переноса. */


/* ========================================================================== 
 * allocate_entity_copy  |  CS:0B58
 * Назначение: Ищет первый слот с очищенным битом RENDER и копирует в него ровно 23 байта.
 * Вход: DS:SI = шаблон записи.
 * Эффект/ограничения: SI=адрес копии либо 0. ES=сегмент игры; DI и CX изменяются. Не проверяет flags==0.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type allocate_entity_copy, @function
allocate_entity_copy:
    .set relocation_0b59, . + 1

    # Свободный слот = EF_RENDER сброшен, не обязательно flags==0. Эта разница влияет на переиспользование.
    mov ax, OFFSET DATA_SEGMENT                                      # CS:0B58
    mov es, ax                                                       # CS:0B5B
    mov di, OFFSET D_entity_records                                  # CS:0B5D
L_allocate_find_slot:
    mov al, BYTE PTR [di+E_FLAGS]                                    # CS:0B60
    test al, EF_SENTINEL                                                    # CS:0B62
    jne L_allocate_pool_full                                         # CS:0B64
    test al, EF_RENDER                                                     # CS:0B66
    jne L_allocate_next_slot                                         # CS:0B68

    # Копируем все 23 байта шаблона. После REP SI возвращается на начало новой записи.
    push di                                                          # CS:0B6A
    mov cx, ENTITY_SIZE                                              # CS:0B6B
    cld                                                              # CS:0B6E
    rep movs BYTE PTR es:[di], BYTE PTR ds:[si]      # CS:0B6F
    pop si                                                           # CS:0B71
    ret                                                              # CS:0B72
L_allocate_next_slot:
    add di, ENTITY_SIZE                                              # CS:0B73
    jmp L_allocate_find_slot                                         # CS:0B76
L_allocate_pool_full:
    mov si, 0x0                                                      # CS:0B78
    ret                                                              # CS:0B7B

/* ========================================================================== 
 * clear_entities  |  CS:0B7C
 * Назначение: Очищает только flags каждой записи до sentinel.
 * Вход: DS = сегмент игры.
 * Эффект/ограничения: Остальные 22 байта слота остаются прежними; не заменять memset всего массива без проверки.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type clear_entities, @function
clear_entities:

    # Очищается только flags каждого слота. Остальные 22 байта намеренно остаются прежними.
    mov si, OFFSET D_entity_records                                  # CS:0B7C
L_clear_next_record:
    mov al, BYTE PTR [si+E_FLAGS]                                    # CS:0B7F
    test al, EF_SENTINEL                                                    # CS:0B81
    jne L_clear_done                                                 # CS:0B83
    mov BYTE PTR [si+E_FLAGS], 0x0                                   # CS:0B85
    add si, ENTITY_SIZE                                              # CS:0B88
    jmp L_clear_next_record                                          # CS:0B8B
L_clear_done:
    ret                                                              # CS:0B8D

/* ========================================================================== 
 * render_entities  |  CS:0B8E
 * Назначение: Семь проходов по пулу: рисует активные записи слоя 7,6,...,1.
 * Вход: DS = сегмент игры.
 * Эффект/ограничения: Слой 0 не рисуется; порядок внутри слоя — порядок слотов. Stride=40, clipping включён.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type render_entities, @function
render_entities:

    # Порядок слоёв 7→1 и порядок слотов внутри слоя фиксированы оригиналом.
    mov ax, ds:[D_video_draw_segment]                                # CS:0B8E
    mov ds:[D_sprite_dest_segment], ax                               # CS:0B91
    mov WORD PTR cs:[CS_sprite_stride], 0x28                         # CS:0B94 | CS-local DATA write, not an opcode patch
    mov WORD PTR ds:[D_sprite_clip_enabled], 0x1                     # CS:0B9B
    mov cx, 0x7                                                      # CS:0BA1
L_render_next_layer:
    mov si, OFFSET D_entity_records                                  # CS:0BA4
L_render_next_entity:
    mov al, BYTE PTR [si+E_FLAGS]                                    # CS:0BA7
    test al, EF_SENTINEL                                                    # CS:0BA9
    jne L_render_advance_layer                                       # CS:0BAB
    test al, EF_RENDER                                                     # CS:0BAD
    je L_render_advance_entity                                       # CS:0BAF
    cmp cl, BYTE PTR [si+E_LAYER]                                    # CS:0BB1
    jne L_render_advance_entity                                      # CS:0BB4
    push cx                                                          # CS:0BB6
    push si                                                          # CS:0BB7
    call prepare_sprite_blit                                         # CS:0BB8
    pop si                                                           # CS:0BBB
    pop cx                                                           # CS:0BBC
L_render_advance_entity:
    add si, ENTITY_SIZE                                              # CS:0BBD
    jmp L_render_next_entity                                         # CS:0BC0
L_render_advance_layer:
    loop L_render_next_layer                                         # CS:0BC2
    ret                                                              # CS:0BC4

/* ========================================================================== 
 * render_entity_to_a800  |  CS:0BC5
 * Назначение: Рисует одну запись в карту-фон A800h, а не в экранную страницу.
 * Вход: DS:SI = сущность/шаблон.
 * Эффект/ограничения: Stride=32, экранное отсечение отключено.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type render_entity_to_a800, @function
render_entity_to_a800:
    mov ax, 0xa800                                                   # CS:0BC5
    mov ds:[D_sprite_dest_segment], ax                               # CS:0BC8
    mov WORD PTR cs:[CS_sprite_stride], 0x20                         # CS:0BCB | CS-local DATA write, not an opcode patch
    mov WORD PTR ds:[D_sprite_clip_enabled], 0x0                     # CS:0BD2
    call prepare_sprite_blit                                         # CS:0BD8
    ret                                                              # CS:0BDB

/* ========================================================================== 
 * prepare_sprite_blit  |  CS:0BDC
 * Назначение: Из записи вычисляет верхний левый угол, размеры, банк изображения и прозрачный цвет.
 * Вход: DS:SI = сущность.
 * Эффект/ограничения: x'=x-signed(anchor_x); y'=y-signed8(z+anchor_y). Передаёт четыре слова через стек.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type prepare_sprite_blit, @function
prepare_sprite_blit:

    # Проекция anchor: X = x-sign8(anchor_x); Y = y-sign8(z+anchor_y). Сумма z+anchor сначала 8-битная.
    mov al, BYTE PTR [si+E_ANCHOR_X]                                 # CS:0BDC
    cbw                                                              # CS:0BDF
    mov bx, WORD PTR [si+E_X]                                        # CS:0BE0
    {load} sub bx, ax                                                # CS:0BE3
    push bx                                                          # CS:0BE5
    mov al, BYTE PTR [si+E_Z]                                        # CS:0BE6
    add al, BYTE PTR [si+E_ANCHOR_Y]                                 # CS:0BE9
    cbw                                                              # CS:0BEC
    neg ax                                                           # CS:0BED
    add ax, WORD PTR [si+E_Y]                                        # CS:0BEF
    push ax                                                          # CS:0BF2
    mov al, BYTE PTR [si+E_WIDTH]                                    # CS:0BF3
    mov ah, 0x0                                                      # CS:0BF6
    push ax                                                          # CS:0BF8
    mov al, BYTE PTR [si+E_HEIGHT]                                   # CS:0BF9
    mov ah, 0x0                                                      # CS:0BFC
    push ax                                                          # CS:0BFE

    # E_BANK уже является байтовым offset таблицы сегментов. Дополнительное умножение на 2 будет ошибкой.
    mov bx, WORD PTR [si+E_BANK]                                     # CS:0BFF
    mov bx, WORD PTR [bx+D_segment_bird1]                            # CS:0C02
    mov al, BYTE PTR [si+E_TRANSPARENT]                              # CS:0C06
    mov cs:[CS_transparent_color], al                                # CS:0C09
    {load} mov cl, al                                                # CS:0C0D
    shl cl, 1                                                        # CS:0C0F
    shl cl, 1                                                        # CS:0C11
    shl cl, 1                                                        # CS:0C13
    shl cl, 1                                                        # CS:0C15
    {load} or al, cl                                                 # CS:0C17
    mov cs:[CS_transparent_pair], al                                 # CS:0C19
    mov si, WORD PTR [si+E_SPRITE]                                   # CS:0C1D
    call blit_sprite                                                 # CS:0C20
    ret                                                              # CS:0C23

/* END src/code/06_entity_pool.asm */
/* BEGIN src/code/07_sprite_blitter.asm */
/* Packed4bpp → EGA и отсечение
 * Физический порядок EXE сохранён. Контракты получены анализом, не авторскими символами.
 * docs/FUNCTIONS_RU.md — индекс; docs/PORTING_TO_C_RU.md — ограничения переноса. */


/* ========================================================================== 
 * blit_sprite  |  CS:0C24
 * Назначение: Отсекает и выводит packed-4bpp sprite через EGA write mode 2; сохраняет прозрачный цвет.
 * Вход: [BP+4]=height, +6=width, +8=y, +10=x; BX=segment; SI=source offset.
 * Эффект/ограничения: RET 8; DS восстанавливается. Горизонтальная граница сдвигает x целиком, не обрезает источник; ширина обрабатывается парами пикселей.
 * Возвраты в физическом диапазоне: ret, ret 0x8.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type blit_sprite, @function
blit_sprite:

    # Stack ABI: height,width,y,x по BP+4,+6,+8,+10. Процедура сама снимает 8 байт аргументов.
    push bp                                                          # CS:0C24
    {load} mov bp, sp                                                # CS:0C25
    mov ax, ds:[D_sprite_clip_enabled]                               # CS:0C27
    ACC16 cmp, 0x0                                                   # CS:0C2A
    jne L_blit_clip_to_viewport                                      # CS:0C2D
    jmp L_blit_setup_ega                                             # CS:0C2F
L_blit_clip_to_viewport:

    # Разность Y нормализуется в кольце 1024 и интерпретируется как диапазон [-512,511].
    mov ax, WORD PTR [bp+BLIT_Y]                                     # CS:0C32
    sub ax, WORD PTR ds:[D_camera_y]                                 # CS:0C35
    ACC16 and, WORLD_Y_MASK                                          # CS:0C39
    test ax, 0x200                                                   # CS:0C3C
    je L_blit_y_signed                                               # CS:0C3F
    ACC16 or, 0xfc00                                                 # CS:0C41
L_blit_y_signed:
    mov WORD PTR [bp+BLIT_Y], ax                                     # CS:0C44
    ACC16 cmp, 0x0                                                   # CS:0C47
    jge L_blit_clip_bottom                                           # CS:0C4A
    add WORD PTR [bp+BLIT_HEIGHT], ax                                # CS:0C4C
    jns L_blit_sprite_0c54                                           # CS:0C4F
    jmp L_blit_return                                                # CS:0C51
L_blit_sprite_0c54:
    jne L_blit_skip_source_rows                                      # CS:0C54
    jmp L_blit_return                                                # CS:0C56
L_blit_skip_source_rows:

    # Срез сверху: сместить packed source на число пропущенных строк *160 байт.
    neg ax                                                           # CS:0C59
    shl ax, 1                                                        # CS:0C5B
    shl ax, 1                                                        # CS:0C5D
    shl ax, 1                                                        # CS:0C5F
    {load} mov cx, ax                                                # CS:0C61
    shl ax, 1                                                        # CS:0C63
    shl ax, 1                                                        # CS:0C65
    {load} add cx, ax                                                # CS:0C67
    shl cx, 1                                                        # CS:0C69
    shl cx, 1                                                        # CS:0C6B
    {load} add si, cx                                                # CS:0C6D
    mov ax, 0x0                                                      # CS:0C6F
    mov WORD PTR [bp+BLIT_Y], ax                                     # CS:0C72
    jmp L_blit_add_viewport_origin                                   # CS:0C75
L_blit_clip_bottom:
    add ax, WORD PTR [bp+BLIT_HEIGHT]                                # CS:0C77
    ACC16 sub, 0xa0                                                  # CS:0C7A
    js L_blit_add_viewport_origin                                    # CS:0C7D
    neg ax                                                           # CS:0C7F
    add ax, WORD PTR [bp+BLIT_HEIGHT]                                # CS:0C81
    ACC16 cmp, 0x0                                                   # CS:0C84
    jg L_blit_sprite_0c8c                                            # CS:0C87
    jmp L_blit_return                                                # CS:0C89
L_blit_sprite_0c8c:
    mov WORD PTR [bp+BLIT_HEIGHT], ax                                # CS:0C8C
L_blit_add_viewport_origin:

    # Экранное окно начинается в (32,8). Горизонталь прижимает весь спрайт к краю, а не срезает его!
    mov ax, 0x20                                                     # CS:0C8F
    add WORD PTR [bp+BLIT_X], ax                                     # CS:0C92
    mov ax, 0x8                                                      # CS:0C95
    add WORD PTR [bp+BLIT_Y], ax                                     # CS:0C98
    mov ax, WORD PTR [bp+BLIT_X]                                     # CS:0C9B
    ACC16 cmp, 0x20                                                  # CS:0C9E
    jge L_blit_sprite_0cab                                           # CS:0CA1
    mov ax, 0x20                                                     # CS:0CA3
    mov WORD PTR [bp+BLIT_X], ax                                     # CS:0CA6
    jmp L_blit_setup_ega                                             # CS:0CA9
L_blit_sprite_0cab:
    add ax, WORD PTR [bp+BLIT_WIDTH]                                 # CS:0CAB
    ACC16 cmp, 0x120                                                 # CS:0CAE
    jle L_blit_setup_ega                                             # CS:0CB1
    mov ax, 0x120                                                    # CS:0CB3
    sub ax, WORD PTR [bp+BLIT_WIDTH]                                 # CS:0CB6
    mov WORD PTR [bp+BLIT_X], ax                                     # CS:0CB9
L_blit_setup_ega:

    # Ниже DS временно меняется на банк пикселей. Операнды [si] здесь НЕ являются Entity.
    push ds                                                          # CS:0CBC
    push bx                                                          # CS:0CBD
    mov dx, 0x3ce                                                    # CS:0CBE
    mov ax, 0xa05                                                    # CS:0CC1
    out dx, ax                                                       # CS:0CC4
    mov ax, 0x7                                                      # CS:0CC5
    out dx, ax                                                       # CS:0CC8
    mov ax, WORD PTR [bp+BLIT_X]                                     # CS:0CC9
    mov bx, WORD PTR [bp+BLIT_Y]                                     # CS:0CCC
    push cx                                                          # CS:0CCF
    shl bx, 1                                                        # CS:0CD0
    shl bx, 1                                                        # CS:0CD2
    shl bx, 1                                                        # CS:0CD4
    mov cx, WORD PTR cs:[CS_sprite_stride]                           # CS:0CD6
    cmp cx, 0x28                                                     # CS:0CDB
    jne L_blit_sprite_0ce4                                           # CS:0CDE
    {load} mov di, bx                                                # CS:0CE0
    jmp L_blit_sprite_0ce7                                           # CS:0CE2
L_blit_sprite_0ce4:
    mov di, 0x0                                                      # CS:0CE4
L_blit_sprite_0ce7:
    shl bx, 1                                                        # CS:0CE7
    shl bx, 1                                                        # CS:0CE9
    {load} add di, bx                                                # CS:0CEB
    {load} mov cl, al                                                # CS:0CED
    shr ax, 1                                                        # CS:0CEF
    shr ax, 1                                                        # CS:0CF1
    shr ax, 1                                                        # CS:0CF3
    {load} add di, ax                                                # CS:0CF5
    and cl, 0x7                                                      # CS:0CF7
    mov ax, 0x80                                                     # CS:0CFA
    shr ax, cl                                                       # CS:0CFD
    {load} mov ah, al                                                # CS:0CFF
    mov bx, WORD PTR ds:[D_sprite_dest_segment]                      # CS:0D01
    mov es, bx                                                       # CS:0D05
    pop cx                                                           # CS:0D07

    # Обрабатываются width>>1 пар пикселей. Нечётную ширину нельзя молча дорисовать в C.
    mov cx, WORD PTR [bp+BLIT_WIDTH]                                 # CS:0D08
    shr cx, 1                                                        # CS:0D0B
    mov al, 0x8                                                      # CS:0D0D
    pop ds                                                           # CS:0D0F
    mov bx, WORD PTR [bp+BLIT_HEIGHT]                                # CS:0D10
L_blit_next_row:
    push ax                                                          # CS:0D13
    push bx                                                          # CS:0D14
    push cx                                                          # CS:0D15
    push di                                                          # CS:0D16
    push si                                                          # CS:0D17
L_blit_pixel_pair:

    # Packed4bpp: верхняя тетрада идёт первой. Быстрый путь пропускает сразу пару прозрачных пикселей.
    mov bh, BYTE PTR cs:[CS_transparent_pair]                        # CS:0D18
L_blit_sprite_0d1d:
    mov bl, BYTE PTR [si]                                            # CS:0D1D
    inc si                                                           # CS:0D1F
    {load} cmp bh, bl                                                # CS:0D20
    jne L_blit_nontransparent_pair                                   # CS:0D22
    shr ah, 1                                                        # CS:0D24
    jne L_blit_sprite_0d2f                                           # CS:0D26
    mov ah, 0x40                                                     # CS:0D28
    inc di                                                           # CS:0D2A
    loop L_blit_sprite_0d1d                                          # CS:0D2B
    jmp L_blit_advance_row                                           # CS:0D2D
L_blit_sprite_0d2f:
    shr ah, 1                                                        # CS:0D2F
    jne L_blit_sprite_0d36                                           # CS:0D31
    mov ah, 0x80                                                     # CS:0D33
    inc di                                                           # CS:0D35
L_blit_sprite_0d36:
    loop L_blit_sprite_0d1d                                          # CS:0D36
    jmp L_blit_advance_row                                           # CS:0D38
L_blit_nontransparent_pair:
    {load} mov bh, bl                                                # CS:0D3A
    shr bl, 1                                                        # CS:0D3C
    shr bl, 1                                                        # CS:0D3E
    shr bl, 1                                                        # CS:0D40
    shr bl, 1                                                        # CS:0D42
    cmp bl, BYTE PTR cs:[CS_transparent_color]                       # CS:0D44
    je L_blit_sprite_0d4f                                            # CS:0D49
    out dx, ax                                                       # CS:0D4B
    and BYTE PTR es:[di], bl                                         # CS:0D4C
L_blit_sprite_0d4f:
    shr ah, 1                                                        # CS:0D4F
    jne L_blit_sprite_0d56                                           # CS:0D51
    mov ah, 0x80                                                     # CS:0D53
    inc di                                                           # CS:0D55
L_blit_sprite_0d56:
    and bh, 0xf                                                      # CS:0D56
    cmp bh, BYTE PTR cs:[CS_transparent_color]                       # CS:0D59
    je L_blit_sprite_0d64                                            # CS:0D5E
    out dx, ax                                                       # CS:0D60
    and BYTE PTR es:[di], bh                                         # CS:0D61
L_blit_sprite_0d64:
    shr ah, 1                                                        # CS:0D64
    jne L_blit_sprite_0d6b                                           # CS:0D66
    mov ah, 0x80                                                     # CS:0D68
    inc di                                                           # CS:0D6A
L_blit_sprite_0d6b:
    loop L_blit_pixel_pair                                           # CS:0D6B
L_blit_advance_row:

    # Следующая source-строка всегда через160 байт; destination заворачивается по &0x7FFF.
    pop si                                                           # CS:0D6D
    add si, 0xa0                                                     # CS:0D6E
    pop di                                                           # CS:0D72
    add di, WORD PTR cs:[CS_sprite_stride]                           # CS:0D73
    and di, 0x7fff                                                   # CS:0D78
    pop cx                                                           # CS:0D7C
    pop bx                                                           # CS:0D7D
    pop ax                                                           # CS:0D7E
    dec bx                                                           # CS:0D7F
    jne L_blit_next_row                                              # CS:0D80
    pop ds                                                           # CS:0D82
    mov ax, 0xff08                                                   # CS:0D83
    out dx, ax                                                       # CS:0D86
    mov ax, 0x5                                                      # CS:0D87
    out dx, ax                                                       # CS:0D8A
    mov ax, 0xf07                                                    # CS:0D8B
    out dx, ax                                                       # CS:0D8E
L_blit_return:
    pop bp                                                           # CS:0D8F
    ret 0x8                                                          # CS:0D90

/* CS:0D93: Writable CS-local row stride (word); read/written by the sprite renderer. */
sprite_stride:
    .word 40


/* CS:0D95: Writable CS-local transparent color (byte). */
transparent_color:
    .byte 0x00


/* CS:0D96: Writable CS-local duplicated transparent nibble (byte). */
transparent_pair:
    .byte 0x00

    ret                                                              # CS:0D97 | Не достигнуто текущим статическим CFG; не удалять.

/* END src/code/07_sprite_blitter.asm */
/* BEGIN src/code/08_game_lifecycle.asm */
/* Смена уровней, respawn, вход/выход туннеля
 * Физический порядок EXE сохранён. Контракты получены анализом, не авторскими символами.
 * docs/FUNCTIONS_RU.md — индекс; docs/PORTING_TO_C_RU.md — ограничения переноса. */


/* ========================================================================== 
 * reset_attract_entities  |  CS:0D98
 * Назначение: Сбрасывает камеру и флаг смерти, очищает пул для заставки.
 * Вход: Нет аргументов.
 * Эффект/ограничения: camera_y=26; не загружает новый уровень.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type reset_attract_entities, @function
reset_attract_entities:
    mov WORD PTR ds:[D_camera_y], 0x1a                               # CS:0D98
    mov BYTE PTR ds:[D_player_respawn_pending], 0x0                  # CS:0D9E
    call clear_entities                                              # CS:0DA3
    ret                                                              # CS:0DA6

/* ========================================================================== 
 * start_level_state  |  CS:0DA7
 * Назначение: Сбрасывает маски объектов, готовит карту и состояние игрока.
 * Вход: level_index/part уже выбраны.
 * Эффект/ограничения: Обнуляет запросы восстановления/боковых устройств.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type start_level_state, @function
start_level_state:
    call reset_map_object_masks                                      # CS:0DA7
    call prepare_level_maps                                          # CS:0DAA
    mov BYTE PTR ds:[D_respawn_effect_pending], 0x0                  # CS:0DAD
    mov BYTE PTR ds:[D_left_device_state], 0x0                       # CS:0DB2
    mov BYTE PTR ds:[D_right_device_state], 0x0                      # CS:0DB7
    call reset_player_motion                                         # CS:0DBC
    ret                                                              # CS:0DBF

/* ========================================================================== 
 * advance_level  |  CS:0DC0
 * Назначение: Увеличивает номер пройденного этапа и базовую скорость, циклически переключает level_index 1..7.
 * Вход: DS = сегмент игры.
 * Эффект/ограничения: Сброс масок, новая карта, игрок, шесть collectible-индикаторов.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type advance_level, @function
advance_level:
    inc BYTE PTR ds:[D_stage_counter]                                # CS:0DC0
    mov al, ds:[D_stage_counter]                                     # CS:0DC4
    cmp al, 0x6                                                      # CS:0DC7
    jb L_advance_level_0dd3                                          # CS:0DC9
    mov WORD PTR ds:[D_base_scroll_speed], 0x30                      # CS:0DCB
    jmp L_advance_level_0de5                                         # CS:0DD1
L_advance_level_0dd3:
    cmp al, 0x3                                                      # CS:0DD3
    jb L_advance_level_0ddf                                          # CS:0DD5
    mov WORD PTR ds:[D_base_scroll_speed], 0x20                      # CS:0DD7
    jmp L_advance_level_0de5                                         # CS:0DDD
L_advance_level_0ddf:
    mov WORD PTR ds:[D_base_scroll_speed], 0x10                      # CS:0DDF
L_advance_level_0de5:
    inc BYTE PTR ds:[D_level_index]                                  # CS:0DE5
    mov al, ds:[D_level_index]                                       # CS:0DE9
    cmp al, 0x7                                                      # CS:0DEC
    jbe L_advance_level_0df5                                         # CS:0DEE
    mov BYTE PTR ds:[D_level_index], 0x1                             # CS:0DF0
L_advance_level_0df5:
    call reset_map_object_masks                                      # CS:0DF5
    call prepare_level_maps                                          # CS:0DF8
    mov BYTE PTR ds:[D_respawn_effect_pending], 0x0                  # CS:0DFB
    call reset_player_motion                                         # CS:0E00
    call reset_collectible_hud                                       # CS:0E03
    ret                                                              # CS:0E06

/* ========================================================================== 
 * handle_player_respawn  |  CS:0E07
 * Назначение: Завершает игру при нуле жизней; иначе расходует жизнь и восстанавливает игрока.
 * Вход: player_respawn_pending != 0.
 * Эффект/ограничения: При возврате к part 0 заново готовит карту и HUD-ресурсы.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type handle_player_respawn, @function
handle_player_respawn:
    mov ax, ds:[D_life_count]                                        # CS:0E07
    ACC16 cmp, 0x0                                                   # CS:0E0A
    jne L_handle_player_respawn_0e15                                 # CS:0E0D
    mov BYTE PTR ds:[D_game_loop_end_flag], 0x1                      # CS:0E0F
    ret                                                              # CS:0E14
L_handle_player_respawn_0e15:
    call remove_life                                                 # CS:0E15
    mov al, ds:[D_level_part]                                        # CS:0E18
    cmp al, 0x0                                                      # CS:0E1B
    je L_handle_player_respawn_0e27                                  # CS:0E1D
    mov BYTE PTR ds:[D_level_part], 0x0                              # CS:0E1F
    call prepare_level_maps                                          # CS:0E24
L_handle_player_respawn_0e27:
    call reset_hud_resources                                         # CS:0E27
    mov BYTE PTR ds:[D_respawn_effect_pending], 0x1                  # CS:0E2A
    mov BYTE PTR ds:[D_left_device_state], 0x0                       # CS:0E2F
    mov BYTE PTR ds:[D_right_device_state], 0x0                      # CS:0E34
    call reset_player_motion                                         # CS:0E39
    ret                                                              # CS:0E3C

/* ========================================================================== 
 * reset_player_motion  |  CS:0E3D
 * Назначение: Задаёт камеру из таблицы старта, скорость и исходные счётчики игрока.
 * Вход: level_index, base_scroll_speed.
 * Эффект/ограничения: Затем заново формирует пул видимой области.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type reset_player_motion, @function
reset_player_motion:
    mov bl, BYTE PTR ds:[D_level_index]                              # CS:0E3D
    mov bh, 0x0                                                      # CS:0E41
    shl bx, 1                                                        # CS:0E43
    mov ax, WORD PTR [bx+D_level_start_y]                            # CS:0E45
    ACC16 and, WORLD_Y_MASK                                          # CS:0E49
    mov ds:[D_camera_y], ax                                          # CS:0E4C
    mov ax, ds:[D_base_scroll_speed]                                 # CS:0E4F
    mov ds:[D_scroll_speed], ax                                      # CS:0E52
    mov WORD PTR ds:[D_surface_resume_x], 0x80                       # CS:0E55
    mov BYTE PTR ds:[D_map_reload_pending], 0x0                      # CS:0E5B
    mov WORD PTR ds:[D_fuel_distance_accumulator], 0x0               # CS:0E60
    mov WORD PTR ds:[D_ammo_use_accumulator], 0x0                    # CS:0E66
    mov BYTE PTR ds:[D_player_respawn_pending], 0x0                  # CS:0E6C
    mov BYTE PTR ds:[D_player_zero_frame_age], 0x0                   # CS:0E71
    mov BYTE PTR ds:[D_side_impact_mask], 0x0                        # CS:0E76
    mov BYTE PTR ds:[D_player_forced_stop], 0x0                      # CS:0E7B
    call rebuild_surface_entities                                    # CS:0E80
    ret                                                              # CS:0E83

/* ========================================================================== 
 * rebuild_surface_entities  |  CS:0E84
 * Назначение: Пересоздаёт игрока и 15 строк объектов, затем боковые устройства и специальные состояния.
 * Вход: camera_y, respawn/side flags.
 * Эффект/ограничения: Пул очищается; игрок занимает первый слот. Некоторые маршруты возвращаются раньше общей инициализации.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type rebuild_surface_entities, @function
rebuild_surface_entities:
    mov al, ds:[D_map_reload_pending]                                # CS:0E84
    cmp al, 0x0                                                      # CS:0E87
    je L_rebuild_surface_entities_0e93                               # CS:0E89
    mov BYTE PTR ds:[D_map_reload_pending], 0x0                      # CS:0E8B
    call prepare_level_maps                                          # CS:0E90
L_rebuild_surface_entities_0e93:
    mov WORD PTR ds:[D_player_x_velocity], 0x0                       # CS:0E93
    call clear_entities                                              # CS:0E99
    mov si, OFFSET D_template_surface_player                         # CS:0E9C
    call allocate_entity_copy                                        # CS:0E9F
    mov ax, ds:[D_surface_resume_x]                                  # CS:0EA2
    mov ds:[D_player_x], ax                                          # CS:0EA5
    call sync_player_to_terrain                                      # CS:0EA8
    mov ax, ds:[D_camera_y]                                          # CS:0EAB
    shr ax, 1                                                        # CS:0EAE
    shr ax, 1                                                        # CS:0EB0
    shr ax, 1                                                        # CS:0EB2
    shr ax, 1                                                        # CS:0EB4
    ACC16 sub, 0x3                                                   # CS:0EB6
    ACC16 and, 0x3f                                                  # CS:0EB9
    mov ds:[D_last_spawn_row], ax                                    # CS:0EBC
    mov cx, 0xf                                                      # CS:0EBF
L_rebuild_surface_entities_0ec2:
    push cx                                                          # CS:0EC2
    push ax                                                          # CS:0EC3
    push ax                                                          # CS:0EC4
    call spawn_map_row                                               # CS:0EC5
    pop ax                                                           # CS:0EC8
    pop cx                                                           # CS:0EC9
    inc ax                                                           # CS:0ECA
    ACC16 and, 0x3f                                                  # CS:0ECB
    loop L_rebuild_surface_entities_0ec2                             # CS:0ECE
    mov al, ds:[D_player_forced_stop]                                # CS:0ED0
    cmp al, 0x0                                                      # CS:0ED3
    je L_rebuild_surface_entities_0eea                               # CS:0ED5
    mov si, OFFSET D_entity_records                                  # CS:0ED7
    mov bx, OFFSET D_sprite_frames_0d49                              # CS:0EDA
    mov BYTE PTR [si+E_FRAME], 0xa                                   # CS:0EDD
    call apply_sprite_frame                                          # CS:0EE1
    mov BYTE PTR ds:[D_player_handler], 0x23                         # CS:0EE4
    ret                                                              # CS:0EE9
L_rebuild_surface_entities_0eea:
    mov al, ds:[D_respawn_effect_pending]                            # CS:0EEA
    cmp al, 0x0                                                      # CS:0EED
    je L_rebuild_surface_entities_0f08                               # CS:0EEF
    mov BYTE PTR ds:[D_respawn_effect_pending], 0x0                  # CS:0EF1
    mov si, OFFSET D_template_respawn_effect                         # CS:0EF6
    mov ax, ds:[D_player_y]                                          # CS:0EF9
    mov WORD PTR [si+E_Y], ax                                        # CS:0EFC
    mov al, ds:[D_player_z]                                          # CS:0EFF
    mov BYTE PTR [si+E_Z], al                                        # CS:0F02
    call allocate_entity_copy                                        # CS:0F05
L_rebuild_surface_entities_0f08:
    call reset_player_history                                        # CS:0F08
    mov al, ds:[D_left_device_state]                                 # CS:0F0B
    cmp al, 0x0                                                      # CS:0F0E
    je L_rebuild_surface_entities_0f23                               # CS:0F10
    mov BYTE PTR ds:[D_left_device_state], 0x1                       # CS:0F12
    mov si, OFFSET D_template_side_device                            # CS:0F17
    and BYTE PTR [si+E_FLAGS], 0xdf                                  # CS:0F1A
    call position_side_device                                        # CS:0F1D
    call allocate_entity_copy                                        # CS:0F20
L_rebuild_surface_entities_0f23:
    mov al, ds:[D_right_device_state]                                # CS:0F23
    cmp al, 0x0                                                      # CS:0F26
    je L_rebuild_surface_entities_0f3b                               # CS:0F28
    mov BYTE PTR ds:[D_right_device_state], 0x1                      # CS:0F2A
    mov si, OFFSET D_template_side_device                            # CS:0F2F
    or BYTE PTR [si+E_FLAGS], 0x20                                   # CS:0F32
    call position_side_device                                        # CS:0F35
    call allocate_entity_copy                                        # CS:0F38
L_rebuild_surface_entities_0f3b:
    ret                                                              # CS:0F3B

/* ========================================================================== 
 * enter_tunnel_mode  |  CS:0F3C
 * Назначение: Инициализирует туннель, дистанцию, угловую динамику и новый пул сущностей.
 * Вход: tunnel mode выбран вызывающей стороной.
 * Эффект/ограничения: Использует другие шаблоны игрока и боковых устройств.
 * Возвраты в физическом диапазоне: ret.
 * Регистровый ABI не является C ABI; сохранность регистров проверять вместе с callees.
 * ========================================================================== */
.type enter_tunnel_mode, @function
enter_tunnel_mode:
    mov BYTE PTR ds:[D_tunnel_flash_state], 0x0                      # CS:0F3C
    call select_tunnel_pattern                                       # CS:0F41
    mov WORD PTR ds:[D_camera_y], 0x1a                               # CS:0F44
    mov WORD PTR ds:[D_tunnel_distance], 0x0                         # CS:0F4A
    mov WORD PTR ds:[D_tunnel_angular_velocity], 0x0                 # CS:0F50
    mov BYTE PTR ds:[D_tunnel_exit_spawned], 0x0                     # CS:0F56
    mov BYTE PTR ds:[D_tunnel_min_radius], 0x3                       # CS:0F5B
    call clear_entities                                              # CS:0F60
    mov si, OFFSET D_template_tunnel_player                          # CS:0F63
    call allocate_entity_copy                                        # CS:0F66
    call reset_tunnel_angle_history                                  # CS:0F69
    mov al, ds:[D_left_device_state]                                 # CS:0F6C
    cmp al, 0x0                                                      # CS:0F6F
    je L_enter_tunnel_mode_0f84                                      # CS:0F71
    mov BYTE PTR ds:[D_left_device_state], 0x1                       # CS:0F73
    mov si, OFFSET D_template_tunnel_side                            # CS:0F78
    and BYTE PTR [si+E_FLAGS], 0xdf                                  # CS:0F7B
    call update_tunnel_side_device                                   # CS:0F7E
    call allocate_entity_copy                                        # CS:0F81
L_enter_tunnel_mode_0f84:
    mov al, ds:[D_right_device_state]                                # CS:0F84
    cmp al, 0x0                                                      # CS:0F87
    je L_enter_tunnel_mode_0f9c                                      # CS:0F89
    mov BYTE PTR ds:[D_right_device_state], 0x1                      # CS:0F8B
    mov si, OFFSET D_template_tunnel_side                            # CS:0F90
    or BYTE PTR [si+E_FLAGS], 0x20                                   # CS:0F93
    call update_tunnel_side_device                                   # CS:0F96
    call allocate_entity_copy                                        # CS:0F99
L_enter_tunnel_mode_0f9c:
    ret                                                              # CS:0F9C

/* ========================================================================== 
 * reset_player_history  |  CS:0F9D
 * Назначение: Заполняет четыре сохранённых позиции/кадра/высоты текущими значениями игрока.
