    mov ds:[D_player_history_frame0], al                             # CS:0FBE
    mov ds:[D_player_history_frame1], al                             # CS:0FC1
    mov ds:[D_player_history_frame2], al                             # CS:0FC4
    mov ds:[D_player_history_frame3], al                             # CS:0FC7
